mapper.select:
select scope, application_id, allowed_max_profile, revision, policy_hash, modified_by, created_at, updated_at from script_capability_policy where scope = 'APPLICATION'
and application_id = #{applicationId}
order by updated_at desc

mapper.update:
update script_capability_policy
   set allowed_max_profile = #{policy.allowedMaxProfile},
       revision = #{policy.revision},
       policy_hash = #{policy.policyHash},
       modified_by = #{policy.modifiedBy},
       updated_at = #{policy.updatedAt}
 where scope = #{policy.scope}
   and application_id = #{policy.applicationId}
   and revision = #{expectedRevision}
